customCSS:
.t, .history { color: #0000ff; }
.join { color: #2e8b57; }
.part, .quit { color: #0000ff; }
.kick, .error { color: #ff0000; }
.notice { color: #a52a2a; }
.action { color: #6a0dad; }
.mode, .nick, .topic, .server { color: #008787; }
.highlight { color: #000000; background-color: #d0d0d0; border-left: 3px solid #6a0dad; padding-left: 8px; }
.reply { color: #0000ff; border-left: 2px solid #0000ff; padding-left: 6px; }
.oper { color: #e4e4e4; background-color: #a52a2a; }
.reactions { color: #0000ff; background-color: #d0d0d0; }
.card { background-color: #d0d0d0; border-color: #0000ff; }
.card-title { color: #0000ff; }
.card-desc { color: #0000ff; }
.daychange { color: #0000ff; border-color: #d0d0d0; }
